function stableStringify(value) {
  if (value === null || typeof value !== 'object') return JSON.stringify(value);
  if (Array.isArray(value)) return '[' + value.map(stableStringify).join(',') + ']';
  return '{' + Object.keys(value).sort().map((key) => JSON.stringify(key) + ':' + stableStringify(value[key])).join(',') + '}';
}

function hash16(input) {
  let h1 = 0xdeadbeef ^ input.length;
  let h2 = 0x41c6ce57 ^ input.length;
  for (let i = 0; i < input.length; i++) {
    const ch = input.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return ((h2 >>> 0).toString(16).padStart(8, '0') + (h1 >>> 0).toString(16).padStart(8, '0')).slice(0, 16);
}

function hash32(input) {
  return hash16('a:' + input) + hash16('b:' + input);
}

function isSensitiveKey(key) {
  const k = String(key || '').toLowerCase();
  const compact = k.replace(/[^a-z0-9]/g, '');
  return k.includes('authorization') || k.includes('cookie') || k.includes('token') || k.includes('secret') || k.includes('password') || k.includes('credential') || k.includes('api-key') || k.includes('api_key') || compact.includes('apikey') || compact.includes('accesskey') || compact.includes('privatekey') || compact.includes('clientsecret');
}

function redactValue(value) {
  if (value === null || value === undefined) return value;
  if (Array.isArray(value)) return value.map(redactValue);
  if (typeof value !== 'object') return value;
  const result = {};
  for (const [rawKey, rawValue] of Object.entries(value)) {
    const key = String(rawKey || '').toLowerCase();
    result[key] = isSensitiveKey(key) ? '[REDACTED]' : redactValue(rawValue);
  }
  return result;
}

const input = $input.first().json || {};
const rawBody = input.body || {};
const rawQuery = input.query || {};
const rawHeaders = input.headers || {};
const headerMap = Object.fromEntries(Object.entries(rawHeaders).map(([key, value]) => [String(key).toLowerCase(), value]));
const body = redactValue(rawBody);
const query = redactValue(rawQuery);
const headers = redactValue(rawHeaders);
const repositoryFullName = rawBody.repository_full_name || rawQuery.repository_full_name || 'Viktoryyyyy/moex-robot';

if (repositoryFullName !== 'Viktoryyyyy/moex-robot') {
  throw new Error('Unsupported repository_full_name');
}

const clientIdempotencyKey = headerMap['idempotency-key'] || headerMap['x-idempotency-key'] || rawBody.idempotency_key || rawQuery.idempotency_key || '';
const idempotencySource = clientIdempotencyKey || stableStringify({ project: 'MOEX Bot', route: 'Route B', spec_version: '1.10.3', repository_full_name: repositoryFullName, body: rawBody, query: rawQuery });
const idempotencyKey = String(clientIdempotencyKey || hash32(idempotencySource));
const runHash = hash32('workflow_run_id:' + idempotencyKey);
const workflowRunId = 'route_b_' + runHash;
const targetBranchName = 'n8n/route-b-' + runHash.slice(0, 12);

const intakePayload = {
  received_at: new Date().toISOString(),
  workflow_name: 'MOEX_ROUTE_B_INTAKE_ACK_V1_10_3',
  spec_version: '1.10.3',
  request: {
    headers,
    query,
    body
  },
  controls: {
    async_dispatch: 'postgres_queue_only',
    execute_subworkflow_primary_dispatch: false,
    max_retries: 3,
    branch_source: 'deterministic_workflow_generated'
  }
};

return [
  {
    json: {
      workflow_run_id: workflowRunId,
      idempotency_key: idempotencyKey,
      repository_full_name: repositoryFullName,
      current_phase: 'intake_ack',
      target_branch_name: targetBranchName,
      status: 'queued',
      current_state: 'queued',
      max_retries: 3,
      event_type: 'intake_ack',
      event_payload_json: JSON.stringify(intakePayload)
    }
  }
];
